    r,g,b=c
    return r>70 and r<175 and r-g>25 and r-b>45
# identify leg columns: brown present at a row well below tabletop
for row in (470,455,440,425,410,395,380):
    runs=[];cur=None
    for u in range(512):
        if isbrown(px[u,row]):
            if cur is None: cur=u
        else:
            if cur is not None: runs.append((cur,u-1)); cur=None
    if cur is not None: runs.append((cur,511))
    print(row,runs)
